import string
import random

def task_func(text, seed=None):
    if text == "":
        raise ValueError("If the input text is empty.")

    rng = random.Random(seed)
    result = []

    for ch in text:
        if ch in string.ascii_letters:
            result.append(rng.choice(string.ascii_lowercase))
        elif ch in string.digits:
            result.append(rng.choice(string.digits))
        elif ch == " ":
            result.append(rng.choice(string.ascii_lowercase + string.digits))
        else:
            result.append(ch)

    return "".join(result)
